    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and not seen[nr][nc] and grid[nr][nc] == bg:
                seen[nr][nc] = True; q.append((nr, nc))
    out = [row[:] for row in grid]
    labeled = [[False]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == bg and not seen[r][c] and not labeled[r][c]:
                # collect this enclosed region
                comp = []
                dq = deque([(r, c)])
                labeled[r][c] = True
                while dq:
                    cr, cc = dq.popleft()
                    comp.append((cr, cc))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < R and 0 <= nc < C and not labeled[nr][nc] and grid[nr][nc] == bg and not seen[nr][nc]:
                            labeled[nr][nc] = True; dq.append((nr, nc))
                rs = [p[0] for p in comp]; cs = [p[1] for p in comp]
                h = max(rs)-min(rs)+1; w = max(cs)-min(cs)+1
                # fill only if the enclosed region is a solid rectangle
                if len(comp) == h*w:
                    for (cr, cc) in comp:
                        out[cr][cc] = fill
    return out
